// Startup probes: PORT and DATA_FILE edge cases.
import { spawn } from 'node:child_process';
import fs from 'node:fs';
import net from 'node:net';
import path from 'node:path';

const SERVER = path.resolve(import.meta.dirname, '../../server.mjs');
const dir = fs.mkdtempSync(path.join(import.meta.dirname, 'w-'));

function run(env) {
  return new Promise((resolve) => {
    const child = spawn(process.execPath, [SERVER], { cwd: dir, env: { PATH: process.env.PATH, ...env } });
    let out = '';
    let err = '';
    child.stdout.on('data', (d) => { out += d; if (out.includes('\n')) child.kill(); });
    child.stderr.on('data', (d) => { err += d; });
    const t = setTimeout(() => child.kill(), 1500);
    child.on('exit', (code, sig) => { clearTimeout(t); resolve({ code, sig, out, err }); });
  });
}

const cases = [];
for (const p of [undefined, '', '0', '+1', '65536', ' 80', '80 ', '1e3', '٣', '-1', '0x10', 'abc', '00000', '99999999999999999999']) {
  cases.push([`PORT=${JSON.stringify(p)}`, { ...(p === undefined ? {} : { PORT: p }), DATA_FILE: 'd.json' }]);
}
fs.mkdirSync(path.join(dir, 'dirfile'));
fs.writeFileSync(path.join(dir, 'empty.json'), '');
fs.writeFileSync(path.join(dir, 'bad.json'), 'nope');
fs.writeFileSync(path.join(dir, 'bom.json'), '﻿{"nextId":1,"bookings":[]}');
fs.writeFileSync(path.join(dir, 'ok.json'), '{"nextId":1,"bookings":[]}');
fs.writeFileSync(path.join(dir, 'arr.json'), '[]');
fs.writeFileSync(path.join(dir, 'null.json'), 'null');
for (const f of ['dirfile', 'empty.json', 'bad.json', 'bom.json', 'arr.json', 'null.json', 'missing/x.json', 'ok.json/x', '', 'ok.json']) {
  cases.push([`DATA_FILE=${JSON.stringify(f)}`, { PORT: '0', DATA_FILE: f }]);
}
cases.push(['bad PORT + bad data (order)', { PORT: 'x', DATA_FILE: 'bad.json' }]);

for (const [label, env] of cases) {
  const r = await run(env);
  console.log(label, '->', JSON.stringify(r));
}
const blocker = net.createServer().listen(0, '127.0.0.1');
await new Promise((r) => blocker.once('listening', r));
const used = String(blocker.address().port);
console.log('in use ->', JSON.stringify(await run({ PORT: used, DATA_FILE: 'd.json' })));
blocker.close();
console.log('files written in cwd:', fs.readdirSync(dir));
fs.rmSync(dir, { recursive: true, force: true });

