// HTTP probes against a real server using raw sockets.
import { spawn } from 'node:child_process';
import fs from 'node:fs';
import net from 'node:net';
import path from 'node:path';

const SERVER = path.resolve(import.meta.dirname, '../../server.mjs');
const dir = fs.mkdtempSync(path.join(import.meta.dirname, 'h-'));

function start(env) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [SERVER], { cwd: dir, env: { PATH: process.env.PATH, PORT: '0', ...env } });
    let out = '';
    child.stderr.on('data', (d) => process.stdout.write(`[stderr] ${d}`));
    child.stdout.on('data', (d) => {
      out += d;
      const m = /:(\d+)\n/.exec(out);
      if (m) resolve({ child, port: Number(m[1]) });
    });
    child.on('exit', (c) => reject(new Error(`exit ${c}`)));
  });
}

function raw(port, text, extra) {
  return new Promise((resolve) => {
    const s = net.connect(port, '127.0.0.1');
    let buf = Buffer.alloc(0);
    s.on('data', (d) => { buf = Buffer.concat([buf, d]); });
    s.on('error', (e) => resolve(`ERR ${e.code}`));
    s.on('close', () => resolve(buf.toString('utf8')));
    s.write(text);
    if (extra) s.write(extra);
    s.end();
  });
}

function req(port, method, target, { headers = {}, body } = {}) {
  const b = body === undefined ? undefined : Buffer.isBuffer(body) ? body : Buffer.from(body);
  const h = { Host: 'x', Connection: 'close', ...headers };
  if (b) h['Content-Length'] = b.length;
  const head = `${method} ${target} HTTP/1.1\r\n${Object.entries(h).map(([k, v]) => `${k}: ${v}`).join('\r\n')}\r\n\r\n`;
  return raw(port, head, b);
}

function summary(text) {
  const [head, ...rest] = text.split('\r\n\r\n');
  const lines = head.split('\r\n');
  const ct = lines.find((l) => /^content-type:/i.test(l)) ?? '';
  return `${lines[0]} | ${ct} | ${rest.join('\r\n\r\n').slice(0, 160)}`;
}

