  ['GET', '/api/bookings?date=2100-01-01'], ['GET', '/api/bookings?date=1999-12-31'], ['GET', '/api/bookings?date=2000-02-29'],
  ['GET', '/api/bookings?date=2100-02-29'], ['GET', '/api/bookings?date=2001-02-29'], ['GET', '/api/bookings?date=2026-11-03+'],
  ['GET', '/?x=1'], ['HEAD', '/'], ['POST', '/app.js'], ['GET', '/app.js?v=2'], ['GET', '/index.html'], ['GET', '//'], ['GET', '*'],
