69	      if (m) {
70	        clearTimeout(timer);
71	        resolve({ ...server, port: Number(m[1]) });
72	      }
73	    };
74	    child.stdout.on('data', check);
75	    exited.then((code) => {
76	      clearTimeout(timer);
77	      reject(new Error(`server exited early (${code}): ${out.stderr}`));
78	    });
79	  });
80	}
